.cinema-bars i:first-child{top:0}
.cinema-bars i:last-child{bottom:0}

/* title flash / chapter card */
.chapter-card{position:absolute;inset:0;z-index:16;display:grid;place-items:center;pointer-events:none;opacity:0;transition:opacity 1s}
.chapter-card.show{opacity:1}
.chapter-card div{text-align:center;padding:30px 50px;position:relative}
