.chapter-card h2{font-size:clamp(34px,5vw,58px);color:#f1e5cf;line-height:1}
.chapter-card p{font-family:var(--serif);font-style:italic;font-size:16px;color:#b8ab94;margin-top:10px}
.chapter-card div::before,.chapter-card div::after{content:"";position:absolute;left:50%;transform:translateX(-50%);width:44px;height:1px;background:rgba(200,164,102,.5)}
.chapter-card div::before{top:0}
.chapter-card div::after{bottom:0}

