/* ============================================================
   THE LITTLE THINGS — core: utilities, save, audio
   ============================================================ */
(function () {
  const LT = (window.LT = window.LT || {});

  const TAU = Math.PI * 2;
  const util = (LT.util = {
    TAU,
    clamp: (v, a, b) => Math.max(a, Math.min(b, v)),
    lerp: (a, b, t) => a + (b - a) * t,
    damp: (a, b, lambda, dt) => a + (b - a) * (1 - Math.exp(-lambda * dt)),
    smooth: (t) => t * t * (3 - 2 * t),
    easeOut: (t) => 1 - Math.pow(1 - t, 3),
    easeInOut: (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2),
    rand: (a = 0, b = 1) => a + Math.random() * (b - a),
    randInt: (a, b) => Math.floor(a + Math.random() * (b - a + 1)),
    chance: (p) => Math.random() < p,
    pick: (arr) => arr[Math.floor(Math.random() * arr.length)],
    dist: (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1),
    rectContains: (r, x, y) => x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h,
    pointInRect: (r, x, y, pad = 0) =>
      x >= r.x - pad && x <= r.x + r.w + pad && y >= r.y - pad && y <= r.y + r.h + pad,
    makeCanvas(w, h, scale = 1) {
      const c = document.createElement('canvas');
      c.width = Math.max(1, Math.round(w * scale));
      c.height = Math.max(1, Math.round(h * scale));
      const ctx = c.getContext('2d');
      ctx.scale(scale, scale);
      return { canvas: c, ctx };
    },
    formatClock(totalSeconds) {
      const m = Math.floor(totalSeconds / 60);
      return m < 1 ? 'just now' : m === 1 ? '1 minute' : m + ' minutes';
    },
    uid: () => Math.random().toString(36).slice(2, 9),
  });

  /* ------------------------------------------------------------
     Save
     ------------------------------------------------------------ */
  const GAME_KEY = 'littlethings.save.v2';
  const SETTINGS_KEY = 'littlethings.settings.v2';

  const defaultSettings = {
    music: 0.5,
    ambience: 0.65,
    sfx: 0.7,
    textSpeed: 1,
    reduceMotion: false,
  };

  const save = (LT.save = {
    GAME_KEY,
    SETTINGS_KEY,
    defaultSettings,
    readSettings() {
      try {
        const raw = localStorage.getItem(SETTINGS_KEY);
        if (!raw) return { ...defaultSettings };
        return { ...defaultSettings, ...JSON.parse(raw) };
      } catch (e) {
        return { ...defaultSettings };
      }
    },
    writeSettings(s) {
      try {
        localStorage.setItem(SETTINGS_KEY, JSON.stringify(s));
      } catch (e) {}
    },
    has() {
      try {
        return !!localStorage.getItem(GAME_KEY);
      } catch (e) {
        return false;
      }
    },
    read() {
      try {
        const raw = localStorage.getItem(GAME_KEY);
        if (!raw) return null;
        const data = JSON.parse(raw);
        if (!data || data.version !== 2) return null;
        return data;
      } catch (e) {
        return null;
      }
    },
    write(state) {
      try {
        state.savedAt = Date.now();
        localStorage.setItem(GAME_KEY, JSON.stringify(state));
        return true;
      } catch (e) {
        return false;
      }
    },
    clear() {
      try {
        localStorage.removeItem(GAME_KEY);
      } catch (e) {}
    },
    meta() {
      const d = save.read();
      if (!d) return null;
      return {
        scene: d.scene,
        ending: d.ending,
        savedAt: d.savedAt,
        playtime: d.playtime || 0,
        name: d.playerName || 'the shopkeeper',
      };
    },
  });

  /* ------------------------------------------------------------
     Audio — entirely synthesized. Rain, rooms, a small piano.
     ------------------------------------------------------------ */
  class AudioEngine {
    constructor() {
      this.ctx = null;
      this.ready = false;
      this.settings = save.readSettings();
      this.scene = 'shop';
      this.started = false;
      this.musicTimer = null;
      this.rainNodes = null;
      this.rainGain = null;
      this.rainFilter = null;
      this.roomGain = null;
      this.musicBus = null;
      this.ambBus = null;
      this.sfxBus = null;
      this.wet = null;
      this.musicStep = 0;
      this.mood = 'shop';
      this.dialogueOpen = false;
      this.tickTimer = null;
      this.lastStep = 0;
      this.clockScene = false;
      this.thunderTimer = null;
      this.noiseBuffer = null;
      this.volume = 1;
    }

    init() {
      if (this.ready) {
        if (this.ctx.state === 'suspended') this.ctx.resume();
        return;
      }
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      try {
        this.ctx = new Ctx();
      } catch (e) {
        return;
      }
      const ctx = this.ctx;
      this.master = ctx.createGain();
      this.master.gain.value = 0.9;
      this.master.connect(ctx.destination);

      this.musicBus = ctx.createGain();
      this.ambBus = ctx.createGain();
      this.sfxBus = ctx.createGain();
      this.musicBus.connect(this.master);
      this.ambBus.connect(this.master);
      this.sfxBus.connect(this.master);

      // reverb
      const convolver = ctx.createConvolver();
      convolver.buffer = this.makeImpulse(2.6, 2.2);
      const wet = ctx.createGain();
      wet.gain.value = 0.36;
      convolver.connect(wet);
      wet.connect(this.master);
      this.reverb = convolver;
      this.wet = wet;
      // send buses
      this.musicSend = ctx.createGain();
      this.musicSend.gain.value = 0.45;
      this.musicSend.connect(convolver);
      this.sfxSend = ctx.createGain();
      this.sfxSend.gain.value = 0.22;
      this.sfxSend.connect(convolver);
      this.musicBus.connect(this.musicSend);
      this.sfxBus.connect(this.sfxSend);

      // noise
      this.noiseBuffer = this.makeNoise(3.5);

      // rain bed
      const rain = ctx.createBufferSource();
      rain.buffer = this.noiseBuffer;
      rain.loop = true;
      const hp = ctx.createBiquadFilter();
      hp.type = 'highpass';
      hp.frequency.value = 420;
      const lp = ctx.createBiquadFilter();
      lp.type = 'lowpass';
      lp.frequency.value = 5200;
      lp.Q.value = 0.4;
      const rg = ctx.createGain();
      rg.gain.value = 0;
      rain.connect(hp);
      hp.connect(lp);
      lp.connect(rg);
      rg.connect(this.ambBus);
      rain.start();
      this.rainNodes = { rain, hp, lp };
      this.rainGain = rg;
      this.rainFilter = lp;

      // low room tone
      const room = ctx.createBufferSource();
      room.buffer = this.noiseBuffer;
      room.loop = true;
      const rlp = ctx.createBiquadFilter();
      rlp.type = 'lowpass';
      rlp.frequency.value = 180;
      const rgn = ctx.createGain();
      rgn.gain.value = 0.18;
      room.connect(rlp);
      rlp.connect(rgn);
      rgn.connect(this.ambBus);
      room.start();
      this.roomGain = rgn;

      this.ready = true;
      this.started = true;
