      }

      /* ---------------- hanging lamps ---------------- */
      const lamp = (x, color) => {
        ctx.strokeStyle = '#2b241a';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, 150);
