      // floor
      ctx.fillStyle = grad(ctx, 0, 480, 0, H, [[0, '#3a2a1d'], [0.5, '#553d28'], [1, '#3a2a1d']]);
      ctx.fillRect(0, 480, W, H - 480);
      for (let row = 0; row < 10; row++) {
        const y = 492 + row * 52;
        ctx.strokeStyle = 'rgba(20,13,8,.35)';
