      ctx.shadowColor = 'transparent';
      // front
      ctx.fillStyle = grad(ctx, bx, by + 64, bx, by + 240, [[0, '#4a3220'], [1, '#2a1b11']]);
      ctx.beginPath();
      ctx.moveTo(bx - 4, by + 64);
      ctx.lineTo(bx + bw - 16, by + 64);
      ctx.lineTo(bx + bw - 22, by + 240);
      ctx.lineTo(bx, by + 240);
      ctx.closePath();
      ctx.fill();
