  /* ------------------------------------------------------------
     STATION
     ------------------------------------------------------------ */
  A.paintStation = function (S) {
    const W = 1900;
    const H = 1000;
    return A.makeScene(W, H, (ctx) => {
      // sky
      ctx.fillStyle = grad(ctx, 0, 0, 0, 620, [
