      ctx.stroke();

      // back wall / station house
      ctx.fillStyle = grad(ctx, 0, 198, 0, 580, [
        [0, '#4c4a3d'],
        [0.35, '#5c5747'],
        [1, '#3a362c'],
      ]);
      ctx.fillRect(0, 198, 1250, 382);
