      // biro train
      ctx.strokeStyle = 'rgba(90,90,110,.5)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(kx + 100, ky + 136);
      ctx.lineTo(kx + 130, ky + 136);
      ctx.lineTo(kx + 136, ky + 128);
      ctx.lineTo(kx + 124, ky + 128);
      ctx.closePath();
      ctx.stroke();

      // station clock
      const scx = 1090, scy = 320;
      ctx.fillStyle = '#2b241a';
