      ctx.fillStyle = '#c9a45c';
      ctx.beginPath();
      ctx.arc(scx + 52, scy + 52, 48, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#efe3cd';
      ctx.beginPath();
      ctx.arc(scx + 52, scy + 52, 41, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(60,44,26,.65)';
      ctx.lineWidth = 1.2;
      for (let i = 0; i < 12; i++) {
        const a = (i / 12) * TAU;
