      case 'ticket':
        drawTicket(ctx, W, H);
        break;
      case 'letter':
        drawLetter(ctx, W, H);
        break;
      case 'ledger':
        drawLedger(ctx, W, H);
        break;
      case 'bluebird':
        drawBluebird(ctx, W, H);
        break;
    }
