285:.person-card{display:flex;gap:14px;padding:12px;background:rgba(255,252,242,.3);border:1px solid rgba(93,75,45,.12)}
286:.person-portrait{width:70px;height:88px;flex:none;background:#1a2423;overflow:hidden;position:relative}
287:.person-portrait canvas{width:100%;height:100%;object-fit:cover}
288:.person-info h3{font-family:var(--serif);font-size:20px;color:#2f281d;line-height:1.1}
289:.person-info .person-role{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-dim);margin:3px 0 6px}
290:.person-info p{font-family:var(--serif);font-size:13.5px;line-height:1.42;color:#5d503c}
291:.person-locked{font-family:var(--serif);font-style:italic;font-size:13px;color:#8d7d62}
292:.place-card{padding:13px 15px;border:1px solid rgba(93,75,45,.14);background:rgba(255,252,242,.25);margin-bottom:10px}
293:.place-card h3{font-family:var(--serif);font-size:20px;color:#2f281d}
294:.place-card .place-sub{font-size:8px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-dim);margin:3px 0 6px}
