297:.evidence-list{display:flex;flex-direction:column;gap:2px}
298:.evidence-row{display:flex;gap:14px;padding:12px 10px;border-bottom:1px solid rgba(93,75,45,.1);cursor:pointer;transition:.18s;align-items:center}
299:.evidence-row:hover{background:rgba(255,252,242,.4)}
300:.evidence-thumb{width:48px;height:48px;flex:none;background:#1c2524;border:1px solid rgba(93,75,45,.2);display:grid;place-items:center;overflow:hidden}
301:.evidence-thumb img{width:100%;height:100%;object-fit:cover}
302:.evidence-info h3{font-family:var(--serif);font-size:17px;color:#332b1f;line-height:1.2}
303:.evidence-info p{font-size:11px;line-height:1.4;color:#77684f;margin-top:2px}
304:.evidence-info .ev-source{font-size:8px;letter-spacing:.15em;text-transform:uppercase;color:var(--gold-dim);margin-top:3px}
305:.evidence-empty{font-family:var(--serif);font-style:italic;font-size:15px;color:#8a795d;padding:20px 0}
308:.inventory-frame{width:min(920px,94vw);max-height:90vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
310:.inventory-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(126px,1fr));gap:10px;padding:4px 30px 20px;overflow-y:auto;min-height:150px}
311:.inv-item{background:rgba(255,252,242,.34);border:1px solid rgba(93,75,45,.16);padding:10px;display:flex;flex-direction:column;
313:.inv-item:hover{background:rgba(255,252,242,.6);border-color:rgba(200,164,102,.6);transform:translateY(-2px)}
314:.inv-thumb{width:100%;aspect-ratio:1.15;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 45%,#2c3532,#131b1a 75%);overflow:hidden}
315:.inv-thumb img{width:100%;height:100%;object-fit:cover}
316:.inv-name{font-family:var(--serif);font-size:14.5px;line-height:1.2;color:#382f22}
317:.inv-tag{font-size:7.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-dim)}
318:.inv-item.new::after{content:"new";position:absolute;top:5px;right:5px;font-size:7px;letter-spacing:.12em;text-transform:uppercase;
320:.inventory-empty{padding:30px;text-align:center;font-family:var(--serif);font-style:italic;color:#8a795d}
321:.inventory-detail{padding:14px 30px 24px;border-top:1px solid rgba(93,75,45,.14);min-height:80px}
322:.inventory-detail h3{font-family:var(--serif);font-size:21px;color:#2f281d}
323:.inventory-detail p{font-family:var(--serif);font-size:14.5px;color:#5d503c;margin-top:4px;line-height:1.45}
326:.board-frame{width:min(1220px,97vw);height:min(800px,94vh);background:linear-gradient(160deg,#222d2b,#141d1d);
328:.board-frame .panel-head{border-bottom:1px solid rgba(200,164,102,.12);padding:20px 26px 15px}
329:.board-frame .panel-head h2{color:#efe3cc}
330:.board-frame .panel-head .eyebrow{color:var(--gold)}
331:.board-frame .icon-btn{border-color:rgba(200,164,102,.25);color:#c0b198}
332:.board-frame .icon-btn:hover{background:rgba(200,164,102,.1);color:#f1e5cf}
333:.board-head-actions{display:flex;align-items:center;gap:20px}
334:.board-frame .text-btn{color:var(--gold)}
335:.board-frame .text-btn:hover{color:#f1e5cf;border-color:#f1e5cf}
336:.board-main{display:flex;flex:1;min-height:0}
337:.board-canvas{flex:1;position:relative;margin:18px;overflow:hidden;border:1px solid rgba(200,164,102,.13);
344:.board-canvas::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 70px rgba(0,0,0,.45)}
345:#boardLines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1}
346:#boardCards{position:absolute;inset:0;z-index:2}
347:.board-empty{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:40px;font-family:var(--serif);font-style:italic;
349:.clue-card{position:absolute;width:142px;min-height:88px;padding:11px 12px 9px;background:linear-gradient(160deg,#efe4cd,#dfcfb0);
352:.clue-card::before{content:"";position:absolute;top:5px;left:50%;transform:translateX(-50%);width:6px;height:6px;border-radius:50%;
354:.clue-card:hover{box-shadow:0 12px 30px rgba(0,0,0,.45)}
355:.clue-card.selected{outline:2px solid var(--amber);outline-offset:2px;transform:translate(-50%,-50%) scale(1.03)}
356:.clue-card.linked{box-shadow:0 8px 22px rgba(0,0,0,.35),0 0 0 1px rgba(168,70,60,.35)}
357:.clue-card.dragging{cursor:grabbing;box-shadow:0 18px 40px rgba(0,0,0,.55);z-index:5;transform:translate(-50%,-50%) scale(1.04)}
358:.clue-card .cc-kicker{font-size:6.5px;letter-spacing:.17em;text-transform:uppercase;color:#967b4e;margin-top:3px}
359:.clue-card .cc-title{font-family:var(--serif);font-size:15.5px;line-height:1.12;color:#31291d;margin-top:3px}
360:.clue-card .cc-sub{font-size:8.5px;line-height:1.3;color:#7d6c51;margin-top:4px}
361:.clue-card.wrong{animation:wrongShake .4s ease}
363:.board-side{width:290px;flex:none;padding:20px 22px;border-left:1px solid rgba(200,164,102,.12);overflow-y:auto;scrollbar-width:thin}
364:.board-instruction{font-family:var(--serif);font-style:italic;font-size:15px;line-height:1.45;color:#c8baa3;margin-bottom:16px}
365:.deductions{display:flex;flex-direction:column;gap:8px}
366:.deduction{padding:10px 12px;border-left:1px solid rgba(200,164,102,.18);background:rgba(255,255,255,.015)}
367:.deduction.found{border-left-color:var(--amber);background:linear-gradient(90deg,rgba(226,169,95,.09),transparent)}
368:.deduction h4{font-family:var(--serif);font-size:15px;color:#9c9282;font-weight:400;line-height:1.2}
369:.deduction.found h4{color:#f0e4ce}
370:.deduction p{font-family:var(--serif);font-size:12.5px;line-height:1.4;color:#8e8372;margin-top:3px;display:none}
371:.deduction.found p{display:block;color:#bcae97}
372:.deduction .d-mark{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold);opacity:.6;display:block;margin-bottom:2px}
373:.board-progress{margin-top:18px;padding-top:14px;border-top:1px solid rgba(200,164,102,.14);font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:#a99c86}
374:.board-progress strong{color:var(--amber);font-weight:500}
375:.board-to-journal{margin-top:16px}
378:.decision{background:radial-gradient(ellipse at 50% 35%,rgba(20,28,28,.75),rgba(4,7,8,.97));backdrop-filter:blur(8px)}
379:.decision-frame{width:min(980px,94vw);text-align:center;position:relative}
380:.decision-frame .eyebrow{color:var(--gold)}
381:.decision-frame h2{font-size:clamp(32px,4vw,50px);color:#f0e4ce;margin:8px 0 8px}

.decision{background:radial-gradient(ellipse at 50% 35%,rgba(20,28,28,.75),rgba(4,7,8,.97));backdrop-filter:blur(8px)}
.decision-frame{width:min(980px,94vw);text-align:center;position:relative}
.decision-frame .eyebrow{color:var(--gold)}
.decision-frame h2{font-size:clamp(32px,4vw,50px);color:#f0e4ce;margin:8px 0 8px}
.decision-lead{font-family:var(--serif);font-style:italic;font-size:16px;color:#b8ab94;max-width:560px;margin:0 auto}
.decision-object{height:180px;margin:10px auto 4px;position:relative}
#decisionCanvas{height:100%;width:auto;max-width:100%;filter:drop-shadow(0 30px 40px rgba(0,0,0,.5))}
.decision-choices{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:10px;text-align:left}
.decision-choice{padding:20px 22px;border:1px solid rgba(200,164,102,.22);background:rgba(10,17,18,.5);transition:.25s;position:relative;overflow:hidden}
.decision-choice:hover{border-color:rgba(226,169,95,.65);background:rgba(226,169,95,.07);transform:translateY(-2px)}
.choice-kicker{display:block;font-size:8px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin-bottom:7px}
.choice-title{display:block;font-family:var(--serif);font-size:21px;line-height:1.2;color:#f1e5cf}
.choice-note{display:block;font-family:var(--serif);font-style:italic;font-size:13.5px;line-height:1.4;color:#a99c86;margin-top:7px}
.decision-cancel{margin-top:20px;color:#8e8372;border-color:transparent}
.decision-cancel:hover{color:#d8cbb4}

/* pause */
.pause-frame{width:min(440px,92vw);text-align:center;padding:38px 34px;background:linear-gradient(165deg,rgba(24,33,33,.97),rgba(11,18,19,.98));
  border:1px solid rgba(200,164,102,.22);box-shadow:var(--shadow)}
.pause-frame h2{font-size:40px;color:#f1e5cf;margin:4px 0 24px}
.pause-list{display:flex;flex-direction:column;gap:2px;text-align:left}
.menu-btn{padding:12px 16px;border-bottom:1px solid rgba(200,164,102,.1);display:flex;justify-content:space-between;align-items:baseline;transition:.2s}
.menu-btn:hover{background:rgba(226,169,95,.08);padding-left:22px}
.menu-btn span{font-family:var(--serif);font-size:17px;color:#e8dcc6}
.menu-btn small{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:#8e8372}
.pause-save{font-size:8.5px;letter-spacing:.16em;text-transform:uppercase;color:#7d7363;margin-top:20px}

/* settings */
.settings-frame{width:min(620px,94vw);max-height:92vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
  box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden}
.settings-body{padding:8px 32px 30px;overflow-y:auto}
.slider-row{display:grid;grid-template-columns:120px 1fr 48px;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid rgba(93,75,45,.12)}
.slider-row span{font-size:11px;letter-spacing:.08em;color:#4b3f2e}
.slider-row output{font-size:10px;color:#8a795d;text-align:right}
input[type=range]{-webkit-appearance:none;appearance:none;height:2px;background:rgba(93,75,45,.25);outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:13px;height:13px;border-radius:50%;background:var(--amber-soft);
  border:2px solid #efe3cd;box-shadow:0 1px 5px rgba(0,0,0,.3);cursor:pointer}
input[type=range]::-moz-range-thumb{width:11px;height:11px;border-radius:50%;background:var(--amber-soft);border:2px solid #efe3cd;cursor:pointer}
.toggle-row{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:14px 0;border-bottom:1px solid rgba(93,75,45,.12)}
.toggle-row span{font-size:11px;letter-spacing:.08em;color:#4b3f2e}
.toggle-row small{display:block;font-size:9px;color:#8a795d;letter-spacing:0;margin-top:2px}
.toggle-row input{width:34px;height:18px;appearance:none;-webkit-appearance:none;background:rgba(93,75,45,.2);border-radius:10px;position:relative;cursor:pointer;transition:.2s}
.toggle-row input::after{content:"";position:absolute;left:2px;top:2px;width:14px;height:14px;border-radius:50%;background:#efe3cd;transition:.2s}
.toggle-row input:checked{background:var(--amber-soft)}
.toggle-row input:checked::after{left:18px}
.settings-note{margin:22px 0 16px;padding:16px;background:rgba(255,252,242,.3);border:1px solid rgba(93,75,45,.12)}
.settings-note p{font-size:11px;line-height:1.55;color:#5d503c}
.settings-note strong{color:#332b1f}
.settings-credit{margin-top:12px;font-family:var(--serif);font-style:italic;font-size:12px;color:#8a795d !important;line-height:1.45}
#fullscreenBtn{color:#6e5d42;border-color:rgba(93,75,45,.3)}

/* howto */
.howto-frame{width:min(620px,94vw);max-height:92vh;background:linear-gradient(160deg,#eee1c9,#e0cfb0);border:1px solid rgba(200,164,102,.5);
  box-shadow:var(--shadow);overflow:hidden;display:flex;flex-direction:column}
.howto-body{padding:6px 32px 30px;overflow-y:auto}
.howto-item{padding:12px 0;border-bottom:1px solid rgba(93,75,45,.12)}
.howto-key{display:inline-block;font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-dim);margin-bottom:4px}
.howto-item p{font-family:var(--serif);font-size:15px;line-height:1.45;color:#4a3f2e}

/* ending */
.ending{z-index:45;background:#081012;display:flex;align-items:center;justify-content:center;padding:0}
#endingCanvas{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.9}
.ending-wash{position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,9,10,.93) 0%,rgba(5,9,10,.72) 44%,rgba(5,9,10,.2) 80%,rgba(5,9,10,.55) 100%)}
.ending-card{position:relative;z-index:2;width:min(560px,88vw);margin-right:auto;margin-left:7vw;max-height:92vh;overflow-y:auto;padding:20px 0}
.ending-eyebrow{font-size:9px;letter-spacing:.26em;text-transform:uppercase;color:var(--gold)}
.ending-card h2{font-size:clamp(42px,5.4vw,68px);line-height:.95;color:#f4ead8;margin:10px 0 20px}
.ending-prose p{font-family:var(--serif);font-size:clamp(16px,1.5vw,19px);line-height:1.6;color:#d3c5ae;margin-bottom:12px}
.ending-prose p:first-child::first-letter{font-size:2.6em;float:left;line-height:.8;padding:6px 8px 0 0;color:var(--amber)}
.ending-quote{font-family:var(--serif);font-style:italic;font-size:16px;line-height:1.5;color:#b8a98f;border-left:1px solid rgba(200,164,102,.4);
  padding-left:16px;margin:20px 0 26px}
.ending-actions{display:flex;align-items:center;gap:22px;flex-wrap:wrap}
.ending-actions .text-btn{color:#a99c86}

/* confirm */
.confirm-frame{width:min(420px,90vw);padding:34px;background:linear-gradient(165deg,#1a2423,#0c1415);border:1px solid rgba(200,164,102,.25);
  box-shadow:var(--shadow);text-align:center}
.confirm-frame h2{font-size:30px;color:#f1e5cf;margin:6px 0 10px}
.confirm-frame p{font-family:var(--serif);font-size:16px;line-height:1.5;color:#bcae97}
.confirm-actions{display:flex;justify-content:center;gap:18px;margin-top:24px;align-items:center}
.confirm-actions .text-btn{color:#9c907b}

/* save pip + fades */
.save-pip{position:absolute;right:26px;bottom:22px;font-size:8px;letter-spacing:.2em;text-transform:uppercase;color:#8d826f;
  opacity:0;transition:opacity .5s;pointer-events:none;z-index:12}
.save-pip.show{opacity:1}
.scene-fade{position:absolute;inset:0;background:#060c0d;opacity:0;pointer-events:none;transition:opacity .55s ease;z-index:14}
.scene-fade.on{opacity:1}
.scene-fade.soft{background:#101a1b}
.cinema-bars{position:absolute;inset:0;pointer-events:none;z-index:13;opacity:0;transition:opacity .6s}
.cinema-bars.on{opacity:1}
.cinema-bars i{position:absolute;left:0;right:0;height:7vh;background:#05090a;display:block}
.cinema-bars i:first-child{top:0}
.cinema-bars i:last-child{bottom:0}

/* title flash / chapter card */
.chapter-card{position:absolute;inset:0;z-index:16;display:grid;place-items:center;pointer-events:none;opacity:0;transition:opacity 1s}
.chapter-card.show{opacity:1}
.chapter-card div{text-align:center;padding:30px 50px;position:relative}
.chapter-card .cc-eyebrow{font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:var(--gold);margin-bottom:10px}
.chapter-card h2{font-size:clamp(34px,5vw,58px);color:#f1e5cf;line-height:1}
.chapter-card p{font-family:var(--serif);font-style:italic;font-size:16px;color:#b8ab94;margin-top:10px}
.chapter-card div::before,.chapter-card div::after{content:"";position:absolute;left:50%;transform:translateX(-50%);width:44px;height:1px;background:rgba(200,164,102,.5)}
.chapter-card div::before{top:0}
.chapter-card div::after{bottom:0}

/* ---------- responsive ---------- */
