  .title-panel{width:min(560px,72vw)}
  .title-side{display:none}
  .dlg-portrait{width:170px}
  .inspect-side{width:280px}
  .board-side{width:240px}
  .journal-grid{grid-template-columns:1fr;gap:24px}
  .journal-frame::after{display:none}
}
