- `renderInspect()` uses `inspectState`.
```
if(!inspectState) return;
const c=$('inspectCanvas'); const g=c.getContext('2d');
const W=900,H=620;
g.setTransform(1.5,0,0,1.5,0,0);
g.clearRect(0,0,W,H);
A.drawObject(g,st.obj.id,W,H,{angle:st.angle,t});
const side=currentSide(st);
for details:
 if(d.side && d.side!==side) continue;
 if(isDetailDiscovered(d)) continue;
 const x=d.x*W,y=d.y*H; const rad=Math.max(18,d.r*Math.min(W,H)); const pulse=...
 A.glow(g,x,y,rad*2.2,'255,200,130',.12+.06*pulse);
 g.strokeStyle=`rgba(255,214,160,${.5+.25*pulse})`; g.lineWidth=1.2; g.beginPath(); g.arc(x,y,10+pulse*3,0,TAU); g.stroke();
 g.fillStyle='rgba(255,225,170,.85)'; g.beginPath(); g.arc(x,y,2.4,0,TAU); g.fill();
