      } else {
        narrate([D.notes.counter]);
      }
      break;
    case 'decorate':
      openPanel('decor');
      break;
    case 'shop_window':
      narrate([D.notes.shop_window]);
      break;
    case 'gramophone':
      AUDIO.play('string');
      narrate([D.notes.gramophone]);
      break;
    case 'cat':
      AUDIO.play('purr');
      narrate([D.notes.cat]);
      break;
    case 'mug':
      AUDIO.play('steam');
      narrate([D.notes.mug]);
      break;
    case 'bluebird':
      openInspect('bluebird');
      break;
    case 'go_street':
      transitionTo('street');
      break;
    case 'go_shop':
      transitionTo('shop');
      break;
    case 'go_clock':
      transitionTo('clock');
      break;
    case 'go_street_clock':
      transitionTo('street');
      break;
    case 'go_station':
      transitionTo('station');
      break;
    case 'go_street_station':
      transitionTo('street');
      break;
    case 'talk_wren':
      talkWren();
      break;
    case 'talk_theo':
      talkTheo();
      break;
    case 'talk_june':
      talkJune();
      break;
    case 'inspect_timetable':
      openInspect('timetable');
      break;
    case 'bench':
      if (!S.clues.bench_carving) {
        effect.clue('bench_carving');
        effect.card('bench');
      }
      narrate([D.notes.bench]);
      break;
    case 'notice':
      narrate([D.notes.notice]);
      break;
    case 'puddle':
      narrate([D.notes.puddle]);
      break;
    case 'street_lamp':
      narrate([D.notes.street_lamp]);
      break;
    case 'workbench':
