  }, { once: true });

  document.addEventListener('click', (e) => {
    const open = e.target.closest('[data-open]');
    if (open) {
      e.preventDefault();
      openPanel(open.dataset.open);
      return;
    }
    const close = e.target.closest('[data-close]');
    if (close) {
      e.preventDefault();
      closeOverlay(close.dataset.close);
    }
  });

  $('dlgClose').addEventListener('click', closeDialogue);
  $('dlgText').addEventListener('click', advanceDialogue);
  $('dlgHint').addEventListener('click', advanceDialogue);

  $('prompt').addEventListener('click', () => {
    const near = nearestHotspot();
    if (near) interactWith(near.h);
  });

  $('journalTabs').addEventListener('click', (e) => {
    const b = e.target.closest('.tab');
    if (!b) return;
    journalTab = b.dataset.tab || 'case';
    AUDIO.play('page');
    renderJournal();
  });

  $('journalPages').addEventListener('click', (e) => {
    const row = e.target.closest('[data-object]');
    if (!row) return;
    const id = row.dataset.object;
    if (D.objects[id]) openInspect(id);
    else toast('A detail', 'It is already in the journal.', '·');
  });

  $('inventoryGrid').addEventListener('click', (e) => {
    const item = e.target.closest('[data-item]');

      const item = e.target.closest('[data-item]');
      if (!item) return;
      selectedItem = item.dataset.item;
      if (S.newItems[selectedItem]) {
        delete S.newItems[selectedItem];
        queueSave();
      }
      renderInventory();
      AUDIO.play('click');
    });

    $('inventoryDetail').addEventListener('click', (e) => {
      const b = e.target.closest('[data-inspect-item]');
      if (b) openInspect(b.dataset.inspectItem);
    });

    $('decorBody').addEventListener('click', (e) => {
      const b = e.target.closest('[data-decor-cat]');
      if (!b || b.disabled) return;
      setDecor(b.dataset.decorCat, b.dataset.decorOpt);
    });

    $('boardHintBtn').addEventListener('click', boardHint);
    $('boardCards').addEventListener('click', (e) => {
      const card = e.target.closest('.clue-card');
      if (!card) return;
      boardCardClick(card.dataset.card);
    });
    $('boardCards').addEventListener('pointerdown', (e) => {
      const card = e.target.closest('.clue-card');
      if (!card || !S) return;
      const id = card.dataset.card;
      const pos = S.cardPos[id];
      if (!pos) return;
      boardDrag = {
        id,
        card,
        startX: e.clientX,
        startY: e.clientY,
        origX: pos.x,
        origY: pos.y,
        moved: false,
      };
      try {
        card.setPointerCapture(e.pointerId);
      } catch (err) {}
    });
    document.addEventListener('pointermove', (e) => {
      if (!boardDrag) return;
      const dx = e.clientX - boardDrag.startX;
      const dy = e.clientY - boardDrag.startY;
      if (Math.abs(dx) + Math.abs(dy) > 5) boardDrag.moved = true;
      if (!boardDrag.moved) return;
      const wrap = $('boardCanvas');
      if (!wrap) return;
      const rect = wrap.getBoundingClientRect();
      const x = clamp(boardDrag.origX + dx / Math.max(1, rect.width), 0.07, 0.93);
      const y = clamp(boardDrag.origY + dy / Math.max(1, rect.height), 0.08, 0.92);
      S.cardPos[boardDrag.id] = { x, y };
      boardDrag.card.style.left = x * 100 + '%';
      boardDrag.card.style.top = y * 100 + '%';
      renderBoardLines();
    });
    document.addEventListener('pointerup', () => {
      if (!boardDrag) return;
      if (boardDrag.moved) {
        suppressBoardClick = true;
        queueSave();
        setTimeout(() => {
          suppressBoardClick = false;
        }, 80);
      }
      boardDrag = null;
      renderBoardLines();
    });

    $('boardProgress').addEventListener('click', (e) => {
      if (e.target.closest('#boardDecide')) {
        closeOverlay('board');
        openDecision();
      }
    });

    const canvas = $('inspectCanvas');
    canvas.addEventListener('pointerdown', (e) => {
      if (!inspectState) return;
      inspectState.dragging = !!inspectState.obj.sides;
      inspectState.startX = e.clientX;
      inspectState.startAngle = inspectState.angle;
      inspectState.moved = 0;
      inspectState.targetAngle = null;
      if (inspectState.dragging) {
        try {
          canvas.setPointerCapture(e.pointerId);
        } catch (err) {}
        canvas.classList.add('dragging');
      }
    });
    canvas.addEventListener('pointermove', (e) => {
      if (!inspectState || !inspectState.dragging) return;
      const dx = e.clientX - inspectState.startX;
      inspectState.moved = Math.max(inspectState.moved, Math.abs(dx));
      inspectState.angle = inspectState.startAngle + dx * 0.018;
    });
    canvas.addEventListener('pointerup', (e) => {
      if (!inspectState) return;
      const moved = inspectState.moved;
      const wasDragging = inspectState.dragging;
      inspectState.dragging = false;
      canvas.classList.remove('dragging');
      if (wasDragging && moved > 5) {
        inspectState.targetAngle = Math.round(inspectState.angle / Math.PI) * Math.PI;
        updateInspectDetails();
        AUDIO.play('page');
        return;
      }
      inspectClick(e);
    });
    canvas.addEventListener('pointercancel', () => {
      if (!inspectState) return;
      inspectState.dragging = false;
      canvas.classList.remove('dragging');
    });

    $('inspectActions').addEventListener('click', (e) => {
      if (!inspectState) return;
      if (e.target.closest('[data-inspect-close]')) {
        closeOverlay('inspect');
        return;
      }
      if (e.target.closest('[data-inspect-turn]')) {
        inspectState.targetAngle = currentInspectSide() === 'front' ? Math.PI : 0;
        AUDIO.play('page');
      }
    });

    $('saveNowBtn').addEventListener('click', () => {
      saveNow(true);
      toast('Saved', 'The evening is tucked away safely.', '✓');
    });
    $('howToBtn').addEventListener('click', () => openPanel('howto'));
    $('toTitleBtn').addEventListener('click', () => {
      showConfirm(
        'Leave the shop?',
        'Return to the title?',
        'Your evening is saved. You can continue from here whenever you like.',
        doReturnTitle
      );
    });

    $('confirmYes').addEventListener('click', () => {
      const cb = confirmCb;
      confirmCb = null;
      closeOverlay('confirm');
      if (cb) cb();
    });
    $('confirmNo').addEventListener('click', () => closeOverlay('confirm'));

    $$('.decision-choice').forEach((b) => {
      b.addEventListener('click', () => chooseEnding(b.dataset.choice));
    });
    $('endingContinue').addEventListener('click', endingContinue);
    $('endingTitleBtn').addEventListener('click', doReturnTitle);

    bindSettings();

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    bindStagePointer();
  }

  function onKeyDown(e) {
    if (e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
    const k = e.key.toLowerCase();
    if (k === 'escape') {
      e.preventDefault();
      const top = overlayStack[overlayStack.length - 1];
      if (!top) {
        if (mode === 'game' && !endingOpen()) openPanel('pause');
        return;
      }
      if (top === 'dialogue') {
        if (dialogueState && dialogueState.node && dialogueState.node.allowLeave !== false) closeDialogue();
        return;
      }
      closeOverlay(top);
      return;
    }

    if (mode !== 'game' || endingOpen()) return;
    if (dialogueState) {
      if (k === ' ' || k === 'enter' || k === 'e') {
        e.preventDefault();
        advanceDialogue();
      }
      return;
    }
    if (isOpen('inspect')) return;

    if (k === 'w' || k === 'a' || k === 's' || k === 'd' || k === 'arrowup' || k === 'arrowdown' || k === 'arrowleft' || k === 'arrowright') {
      keys[k] = true;
      e.preventDefault();
      return;
    }
    if (k === 'e' || k === 'enter') {
      e.preventDefault();
      const near = nearestHotspot();
      if (near) interactWith(near.h);
      return;
    }
    if (k === ' ') {
      e.preventDefault();
      return;
    }
    if (k === 'j') {
      e.preventDefault();
      openPanel('journal');
      return;
    }
    if (k === 'i') {
      e.preventDefault();
      openPanel('inventory');
      return;
    }
    if (k === 'c') {
      e.preventDefault();
      openPanel('board');
      return;
    }
    if (k === 'm') {
      e.preventDefault();
      openPanel('pause');
    }
  }

  function onKeyUp(e) {
    keys[e.key.toLowerCase()] = false;
  }

  function bindStagePointer() {
    stage.addEventListener('pointerdown', (e) => {
      if (mode !== 'game' || isBlocking()) return;
      ensureAudio();
      const rect = stage.getBoundingClientRect();
      pointerDown = {
        id: e.pointerId,
        x: e.clientX,
        y: e.clientY,
        sx: e.clientX - rect.left,
        sy: e.clientY - rect.top,
        type: e.pointerType,
        moved: false,
      };
      if (e.pointerType === 'touch') {
        try {
          stage.setPointerCapture(e.pointerId);
        } catch (err) {}
      }
    });
    stage.addEventListener('pointermove', (e) => {
      if (mode !== 'game' || isBlocking()) {
        hovered = null;
        return;
      }
      const rect = stage.getBoundingClientRect();
      if (pointerDown && pointerDown.id === e.pointerId) {
        const dx = e.clientX - pointerDown.x;
        const dy = e.clientY - pointerDown.y;
        if (Math.hypot(dx, dy) > 14) pointerDown.moved = true;
        if (pointerDown.moved && pointerDown.type === 'touch') {
          joystickVec = { x: clamp(dx / 58, -1, 1), y: clamp(dy / 58, -1, 1) };
          showJoystickAt(pointerDown.x, pointerDown.y, joystickVec);
          hovered = null;
          return;
        }
      } else if (e.pointerType !== 'touch') {
        updateHover(e.clientX - rect.left, e.clientY - rect.top);
      }
    });
    const endPointer = (e) => {
      if (!pointerDown || pointerDown.id !== e.pointerId) return;
      const p = pointerDown;
      pointerDown = null;
      joystickVec = null;
      hideJoystick();
      if (p.moved) return;
      const rect = stage.getBoundingClientRect();
      tapAt(e.clientX - rect.left, e.clientY - rect.top);
    };
    stage.addEventListener('pointerup', endPointer);
    stage.addEventListener('pointercancel', () => {
      pointerDown = null;
      joystickVec = null;
      hideJoystick();
    });
    stage.addEventListener('pointerleave', () => {
      if (mode === 'game' && !pointerDown) hovered = null;
    });
  }

  function updateHover(sx, sy) {
    const wx = sx / cam.scale + cam.x;
    const wy = sy / cam.scale + cam.y;
    let found = null;
    activeHotspots().forEach((h) => {
      if (found) return;
      const rr = Math.max(32, (h.r || 70) * 0.95);
      if (dist(wx, wy, h.x, h.y) < rr) found = h;
    });
    hovered = found;
    stage.style.cursor = found ? 'pointer' : 'default';
  }

  function showJoystickAt(x, y, vec) {
    const joy = $('joystick');
    const stick = $('stick');
    if (!joy) return;
    joy.classList.remove('hidden');
    joy.style.left = x - 56 + 'px';
    joy.style.top = y - 56 + 'px';
    joy.style.bottom = 'auto';
    if (stick) stick.style.transform = 'translate(' + vec.x * 26 + 'px,' + vec.y * 26 + 'px)';
  }

  function hideJoystick() {
    const joy = $('joystick');
    if (!joy) return;
    joy.classList.add('hidden');
    joy.style.top = '';
    joy.style.bottom = '';
    const stick = $('stick');
    if (stick) stick.style.transform = '';
  }

  /* ------------------------------------------------------------
     Main loop
     ------------------------------------------------------------ */
  function frame(now) {
    if (!lastFrame) lastFrame = now;
    dtGlobal = Math.min(0.05, Math.max(0.001, (now - lastFrame) / 1000));
    lastFrame = now;
    tGlobal = now / 1000;
    if (mode === 'title') {
      renderTitle(tGlobal);
    } else if (S) {
      if (!isBlocking()) update(dtGlobal);
      renderWorld();
      if (inspectState) renderInspect();
    }
    if (mode === 'game' && !isBlocking()) updatePrompt();
    else hide($('prompt'));
    requestAnimationFrame(frame);
  }

  /* ------------------------------------------------------------
     Init
     ------------------------------------------------------------ */
  function init() {
    resize();
    applySettings();
    syncSettingsUI();
    buildTitle();
    bindEvents();
    const ic = $('inspectCanvas');
    if (ic) {
      ic.width = 1350;
      ic.height = 930;
    }
    show($('loading'));
    setTimeout(() => hide($('loading')), 480);
    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(() => {
        titleCanvas = null;
        sceneCache = {};
      });
    }
    requestAnimationFrame(frame);
  }

  /* Public API used by the authored story in data.js */
  LT.game = {
    effect,
    openInspect,
    closeDialogue,
    finishIntro,
    saveNow,
    openPanel,
    openDecision,
  };

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();

import { existsSync, readFileSync, writeFileSync, mkdirSync, statSync } from 'node:fs'
import { resolve, join, extname } from 'node:path'
import { createHash } from 'node:crypto'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { pathToFileURL } from 'node:url'
import { child } from './session-lifecycle.mjs'
import { livePreviewScript, watchProject } from './live-preview.mjs'

export function projectType(root) {
  if (existsSync(join(root, 'package.json'))) {
    const p = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
    if (p.dependencies?.next || p.devDependencies?.next) throw new Error('Unsupported framework: customize start.sh and provide static deployment output.')
    if (p.dependencies?.vite || p.devDependencies?.vite) return 'vite'
    throw new Error('Unsupported package project: customize start.sh and deployment output.')
  }
  if (existsSync(join(root, 'index.html'))) return 'html'
  throw new Error('No generated index.html or supported package project.')
}
export async function start(root = process.cwd()) {
  const type = projectType(root)
  const projectRoot = resolve(root)
  if (type === 'vite') {
    const stampDir = process.env.OPENCODE_WEB_DIR || join(root, 'node_modules', '.cache')
    mkdirSync(stampDir, { recursive: true })
    const stamp = join(stampDir, 'default-dependencies')
    const lock = join(root, 'package-lock.json')
    const hash = createHash('sha256').update(readFileSync(join(root, 'package.json'))).update(existsSync(lock) ? readFileSync(lock) : '').digest('hex')
    let old = ''
    try { old = readFileSync(stamp, 'utf8') } catch {}
    if (old !== hash || !existsSync(join(root, 'node_modules/vite'))) {
      await child('npm', [existsSync(lock) ? 'ci' : 'install', '--no-audit', '--no-fund'], { cwd: root })
      mkdirSync(stampDir, { recursive: true })
      const installedHash = createHash('sha256').update(readFileSync(join(root, 'package.json'))).update(existsSync(lock) ? readFileSync(lock) : '').digest('hex')
      writeFileSync(stamp, installedHash)
    }
    await child(process.execPath, [join(root, 'node_modules/vite/bin/vite.js'), 'build', '--base', './'], { cwd: root })
    root = join(root, 'dist')
  }
  if (!existsSync(join(root, 'index.html'))) throw new Error('Static deployment output must contain index.html.')
  if (process.env.OPENCODE_WEB_DIR) writeFileSync(join(process.env.OPENCODE_WEB_DIR, 'deployment-output.json'), JSON.stringify({ project: projectRoot, directory: resolve(root) }))
  const mime = { '.html':'text/html', '.js':'application/javascript', '.css':'text/css', '.json':'application/json', '.svg':'image/svg+xml', '.png':'image/png', '.jpg':'image/jpeg', '.webp':'image/webp', '.wasm':'application/wasm', '.glb':'model/gltf-binary' }
  const clients = new Set()
  const stopWatching = watchProject(root, () => { for (const client of clients) client.write('event: change\ndata: changed\n\n') })
  const keepAlive = setInterval(() => { for (const client of clients) client.write(': keepalive\n\n') }, 20000)
  const buildWatcher = type === 'vite' ? spawn(process.execPath, [join(projectRoot, 'node_modules/vite/bin/vite.js'), 'build', '--base', './', '--watch'], { cwd: projectRoot, stdio: 'inherit' }) : null
  const server = createServer((req, res) => {
    try {
      const url = new URL(req.url, 'http://localhost')
      if (url.pathname === '/__omgithub/live') {
        res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no', Connection: 'keep-alive' })
        res.write(': connected\n\n')
        clients.add(res)
        req.on('close', () => clients.delete(res))
